// v230 : page /memoire servie au telephone (memview.c fournit /api/memoire)
static const char memoire_page[] =
"<!doctype html><html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n"
"<title>GC Station - m\xC3\xA9moire</title><style>\n"
":root{--bg:#0f0b22;--card:#1c1638;--line:#33295e;--fg:#eee9ff;--dim:#a79ccf;--acc:#8b5cff;--blue:#96c8ff;--gold:#ffd278}\n"
"*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:16px/1.4 system-ui,sans-serif}\n"
".w{max-width:560px;margin:0 auto;padding:12px 14px 40px}h1{font-size:20px;margin:4px 0 12px}a{color:var(--acc)}\n"
".card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:14px;margin-bottom:12px}\n"
".k{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.k div{min-width:0}.k small{color:var(--dim);display:block;font-size:13px}.k b{font-size:22px;font-variant-numeric:tabular-nums}\n"
".bar{height:8px;background:#2a2150;border-radius:4px;overflow:hidden;margin-top:12px}.bar i{display:block;height:100%;background:linear-gradient(90deg,#ff78be,#786eff)}\n"
"svg{width:100%;height:120px;display:block}.r{display:flex;align-items:center;gap:10px;padding:6px 0;border-bottom:1px solid var(--line);font-variant-numeric:tabular-nums}\n"
".r span:first-child{flex:0 0 38%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.r .b{flex:1;height:6px;background:#2a2150;border-radius:3px;overflow:hidden}.r .b i{display:block;height:100%;background:var(--blue)}\n"
".r span:last-child{flex:0 0 auto;color:var(--dim);font-size:14px}.h{color:var(--dim);font-size:13px}h3{margin:0 0 6px;font-size:16px}\n"
"</style></head><body><div class=\"w\"><h1>M\xC3\xA9moire de la GameCube</h1>\n"
"<div class=\"card\"><div class=\"k\"><div><small>Libre</small><b id=\"f\">-</b></div><div><small>Plus grand bloc</small><b id=\"g\" style=\"color:var(--gold)\">-</b></div><div><small>Utilis\xC3\xA9" "e</small><b id=\"u\">-</b></div></div>\n"
"<div class=\"bar\"><i id=\"ub\" style=\"width:0\"></i></div><div class=\"h\" id=\"gm\"></div></div>\n"
"<div class=\"card\"><h3>M\xC3\xA9moire libre</h3><svg id=\"c\" viewBox=\"0 0 300 120\" preserveAspectRatio=\"none\"></svg><div class=\"h\" id=\"cm\"></div></div>\n"
"<div class=\"card\"><h3>Par onglet (le moins de m\xC3\xA9moire libre vu)</h3><div id=\"t\"></div></div>\n"
"<div class=\"card\"><h3>Dernier d\xC3\xA9marrage <span id=\"bt\" class=\"h\"></span></h3><div id=\"s\"></div></div>\n"
"<p class=\"h\" id=\"v\"></p><p class=\"h\"><a href=\"/\">\xE2\x86\x90 T\xC3\xA9l\xC3\xA9" "commande</a></p></div><script>\n"
"function $(i){return document.getElementById(i)}\n"
"function mo(b){return(b/1048576).toFixed(1).replace('.',',')+' Mo'}\n"
"function row(n,v,f,t){var r=document.createElement('div');r.className='r';var a=document.createElement('span');a.textContent=n;var b=document.createElement('span');b.className='b';var i=document.createElement('i');i.style.width=Math.max(1,Math.min(100,f*100))+'%';b.appendChild(i);var c=document.createElement('span');c.textContent=t;r.appendChild(a);r.appendChild(b);r.appendChild(c);return r}\n"
"function go(){fetch('/api/memoire').then(r=>r.json()).then(j=>{var tot=j.free+j.used||1;$('f').textContent=mo(j.free);$('u').textContent=mo(j.used);$('g').textContent=j.big?mo(j.big):'-';\n"
"$('ub').style.width=(100*j.used/tot)+'%';$('gm').textContent=j.big?(j.big>=6291456?'Relance directe apr\\u00e8s une mise \\u00e0 jour : possible':'Relance apr\\u00e8s une mise \\u00e0 jour : par le lanceur de secours'):'Plus grand bloc : mesur\\u00e9 quand l\\u2019\\u00e9cran Outils > M\\u00e9moire en direct est ouvert sur la t\\u00e9l\\u00e9';\n"
"var h=j.hist.map(v=>v*1024),hi=Math.max.apply(null,h.concat([1])),lo=Math.min.apply(null,h.concat([hi])),d=Math.max(hi-lo,hi*0.05),p='';lo=Math.max(0,lo-d*0.25);hi=lo+d*1.5;h.forEach((v,i)=>{p+=(i?'L':'M')+(300*(120-h.length+i)/119).toFixed(1)+' '+(116-110*(v-lo)/(hi-lo)).toFixed(1)});\n"
"$('c').innerHTML=h.length>1?'<path d=\"'+p+'\" fill=\"none\" stroke=\"#96c8ff\" stroke-width=\"2\" vector-effect=\"non-scaling-stroke\"/>':'';\n"
"var mn=Math.min.apply(null,h.length?h:[0]),sec=h.length*j.step;$('cm').textContent=h.length?(sec<90?sec+' derni\\u00e8res secondes':Math.round(sec/60)+' derni\\u00e8res minutes')+', minimum '+mo(mn)+', maximum '+mo(Math.max.apply(null,h)):'';\n"
"var T=$('t');T.innerHTML='';j.tabs.sort((a,b)=>a[1]-b[1]).forEach(x=>T.appendChild(row(x[0],0,x[1]*1024/tot,mo(x[1]*1024))));if(!j.tabs.length)T.textContent='(les onglets visit\\u00e9s s\\u2019affichent ici)';\n"
"var S=$('s');S.innerHTML='';var bm=Math.max.apply(null,j.steps.map(x=>x[1]).concat([1]));j.steps.forEach(x=>S.appendChild(row(x[0],0,x[1]/bm,x[1]+' ms')));$('bt').textContent=j.boot?'('+(j.boot/1000).toFixed(1).replace('.',',')+' s)':'';\n"
"$('v').textContent='GC Station '+j.ver+' (build '+j.build+'), allum\\u00e9e depuis '+Math.floor(j.up/60)+' min'}).catch(()=>{$('v').textContent='Pas de r\\u00e9ponse de la GameCube'})}\n"
"go();setInterval(go,3000);\n"
"</script></body></html>\n";
